function animate(env,el,p){
    var t=el.text,out="",cs="!@#$%^&*<>/\\|=+01";
    for(var i=0;i<t.length;i++){ var c=t.charAt(i); if(c==" "){out+=c;continue;}
        var r=(AM.simplexNoise(i*5.1+env.absTime*p.speed, p.seed)+1)/2;
        out += r<p.amount ? cs.charAt(Math.floor(r*1000)%cs.length) : c; }
    el.text=out; return el;
}
